namespace docking.widgets;

using static org.junit.Assert;




using org.junit;
using org.junit;

using docking.widgets.DropDownTextFieldDataModel;
using generic.test;

public class DefaultDropDownSelectionDataModelTest : AbstractGenericTest {

	private DefaultDropDownSelectionDataModel<TestType> model;

	public DefaultDropDownSelectionDataModelTest() : base()
    {
	}

	/* @Before */
	public void setUp()
    {
		List<TestType> data = new();
		data.add(new TestType("abc"));
		data.add(new TestType("baa"));
		data.add(new TestType("bac"));
		data.add(new TestType("bace"));
		data.add(new TestType("bad"));
		data.add(new TestType("cat"));
		data.add(new TestType("zzz"));
		model = new(data, t => t.getName());
	}

	/* @Test */
	public void testGetMatchingData() {
		List<TestType> matchingData = model.getMatchingData("a", SearchMode.STARTS_WITH);
		assertEquals(1, matchingData.size());
		assertEquals("abc", matchingData.get(0).getName());

		matchingData = model.getMatchingData("bac", SearchMode.STARTS_WITH);
		assertEquals(2, matchingData.size());
		assertEquals("bac", matchingData.get(0).getName());
		assertEquals("bace", matchingData.get(1).getName());
	}

	private class TestType {
		private string name;

		TestType(string name) {
			this.name = name;
		}

		string getName() {
			return name;
		}
	}
}
